#define MAX_STEPS 100
#define MAX_DIST 1000.
#define SURF_DIST .01

//GPT Because im lazy.
vec3 rot(vec3 pos, vec3 angles) {
    float cx = cos(angles.x), sx = sin(angles.x);
    float cy = cos(angles.y), sy = sin(angles.y);
    float cz = cos(angles.z), sz = sin(angles.z);

    vec3 xRot = vec3(pos.x, pos.y * cx - pos.z * sx, pos.y * sx + pos.z * cx);
    vec3 yRot = vec3(xRot.x * cy + xRot.z * sy, xRot.y, -xRot.x * sy + xRot.z * cy);
    return vec3(yRot.x * cz - yRot.y * sz, yRot.x * sz + yRot.y * cz, yRot.z);
}


//Iniqo Quilez
float sdTorus( vec3 p, vec2 t ){
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}

float sphere(vec3 p, float r){
    return length(p)-r;
}

float scene(vec3 pos){
    return min(sdTorus(pos, vec2(0.3,0.1)),sphere(pos+vec3(0.0,0.3*sin(iTime),0.0),0.1));
}

float march(vec3 origin, vec3 direction){
    float t = 0.;
    for(int i = 0; i<MAX_STEPS; i++){
        vec3 ray = origin+t*direction;
        float dist = scene(ray);
        t+= dist;
        if(t>MAX_DIST || dist < SURF_DIST) break;
    }
    return t;
}

vec3 normal(vec3 pos) {
	float d = scene(pos);
    // vec2 for swizzling
    vec2 diff = vec2(.01, 0);

    vec3 n = d - vec3(
        scene(pos-diff.xyy),
        scene(pos-diff.yxy),
        scene(pos-diff.yyx));

    return normalize(n);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    //ORTHOGRAPHIC
    vec3 origin_o = vec3(uv.x, uv.y, 1.);
    vec3 dir_o = normalize(vec3(0.0, 0.0, -1));

    //PERSPECTIVE
    vec3 origin_p = vec3(0., 0., 1.);
    vec3 dir_p = normalize(vec3(uv.x, uv.y, -1));

    vec3 origin = mix(origin_o,origin_p,-0.5+0.8*sin(iTime));
    vec3 dir = mix(dir_o,dir_p,-1.+1.*cos(iTime));

    vec3 cam_rot = vec3(sin(iTime),2.*iTime,iTime);
    origin = rot(origin, cam_rot);
    dir = rot(dir, cam_rot);

    float d = march(origin,dir);
    float val = step(fract((20.+5.*sin(iTime))*uv.x+sin(4.5*iTime)),0.5);
    vec3 col = vec3(val);

    // Time varying pixel color
    if(d < MAX_DIST){
        //float b = abs(dot(dir,normal(origin+d*dir)));
        float b = 0.6;
        float uv_c = uv.y;//step(fract(iTime),0.5)*uv.x+step(0.5,fract(iTime))*uv.y;
        val = step(fract((20.+5.*sin(-iTime))*uv_c+sin(-4.5*iTime)),0.5);
        col = val*vec3(0.5+0.3*cos(d*3.+iTime),0.5+0.5*sin(d*2.+0.5*iTime),0.0);
    }
    //col = vec3(val);
    // Output to screen
    fragColor = vec4(col,1.0);
}
